            foreach(var entry in new[]{new[]{"外观与桌面图标","appearance","设置窗口、托盘、快捷方式图标，以及整窗背景和配色。"},new[]{"本地引擎设置","engine","设置 CosyVoice／RVC 的运行环境和默认基础模型位置。"},new[]{"音频输出模式","outputMode","切换本地 TTS 直出或 RVC＋本地 TTS 混合输出。"},new[]{"连接与联动","connections","用清晰的分步流程接入 Harness 或 AIRI，并完成真实播放验证。"},new[]{"高级声音与说话风格","advanced","启用或关闭索引、包络、表达指令、风格和其他高级处理。"},new[]{"音频清理","cleanup","设置生成音频的保留数量、时间和空间上限。"}}){string id=entry[1],note=entry[2];Add(menu,Row(EntryBtn(entry[0],note,()=>ShowPage(id))));}
