            Add(card,Row(AsyncBtn("保存本地 TTS 设置",SaveDraft),Btn("下载推荐引擎",()=>ServiceClient.Open("https://github.com/FunAudioLLM/CosyVoice#model-download")),Btn("打开 CosyVoice 页面",()=>ServiceClient.Open("https://github.com/FunAudioLLM/CosyVoice#advanced-usage")),Btn("打开当前模型目录",()=>ServiceClient.Open(Store.Resolve(baseModelPath.Text.Trim().Length>0?baseModelPath.Text.Trim():Config.engines.cosyModel)))));
            Add(card,Hint("CosyVoice 官方页面提供训练脚本与说明；程序内“训练音色”入口给出分步指导。训练完成后，在首页选取完整模型目录。网页演示与参考音频克隆不等同于训练模型。"));
            Add(card,Hint("运行环境与已下载引擎的位置；完整便携包发布时使用包内相对路径。"));
            PathField(card,"pythonRvc","主服务／RVC Python 运行时","Python|python.exe;pythonw.exe",false);PathField(card,"rvcHome","RVC 基础库目录","",true);PathField(card,"pythonTts","CosyVoice Python 运行时","Python|python.exe;pythonw.exe",false);PathField(card,"cosyRepo","CosyVoice 源码目录","",true);PathField(card,"cosyModel","CosyVoice 预训练模型目录","",true);
            Add(card,Row(AsyncBtn("保存运行环境",async()=>{var next=Json.Copy(Config);next.engines.pythonRvc=fields["pythonRvc"].Text.Trim();next.engines.rvcHome=fields["rvcHome"].Text.Trim();next.engines.pythonTts=fields["pythonTts"].Text.Trim();next.engines.cosyRepo=fields["cosyRepo"].Text.Trim();next.engines.cosyModel=fields["cosyModel"].Text.Trim();if(await Service.Running())throw new InvalidOperationException("请先关闭服务，再切换运行环境。");Store.Write(next);Config=next;Status("运行环境已保存；开启服务后生效。");})));
        }
        void BuildAdvanced(){var card=SettingsCard("advanced","高级声音与说话风格");Add(card,Hint("这些选项保留在高级入口。本地 TTS 语速、参考条件和表达指令影响说话方式；RVC 配置的音调与声线粗细作用于第二次变声。"));var advanced=new CheckBox{Text="启用高级声音与说话风格（默认关闭）",AutoSize=true};checks["advancedEnabled"]=advanced;advanced.CheckedChanged+=(s,e)=>UpdateVoiceControls();Add(card,Row(advanced));Add(card,Hint("关闭时旁路索引检索、包络混合、表达指令、风格、句首裁剪和高级播放音量；参数仍保存。RVC 音调／声线粗细、本地 TTS 模型、参考条件和语速保留。"));processingChoice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=320};processingChoice.Items.AddRange(new object[]{"标准 RVC · 音调与声线粗细","认可版兼容 · 原离线算法"});processingChoice.SelectedIndexChanged+=(s,e)=>{formant.Enabled=processingChoice.SelectedIndex!=1;if(processingChoice.SelectedIndex==1)formant.Value=0;UpdateVoiceControls();};Add(card,Row(Hint("声音处理方式"),processingChoice));Add(card,Hint("认可版兼容保留原离线转换和保护参数，不调整声线粗细。切换标准模式会改变声音处理。"));NumberField(card,"protect","认可版辅音保护（标准模式不使用）",0,.5M,.01M,2);NumberField(card,"indexRate","RVC 索引检索比例",0,1,.05M,2);NumberField(card,"rmsMix","输出音量包络混合",0,1,.05M,2);NumberField(card,"volume","播放音量",0,1.5M,.05M,2);NumberField(card,"leadingSilence","本地 TTS 句首低能量空白保留上限（秒）",.2M,1,.05M,2);Add(card,Hint("RVC 基频算法"));f0Choice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=220};f0Choice.Items.AddRange(new object[]{"rmvpe","harvest","crepe","pm"});Add(card,Row(f0Choice));Field(card,"instruction","CosyVoice 表达指令（留空使用参考音频的说话方式）",true);Add(card,Row(AsyncBtn("保存高级设置",SaveDraft)));}
        void BuildHarness(){
            var stack=Stack(NewPage("harness"));var intro=Card(stack,"Harness 自动接入");
            Add(intro,Hint("一次只处理一个来源：先启动语音服务，再点击该来源的“自动接入并验证”。未检测到连接时会让你选择安装或用户配置目录；程序完成配置后会告诉你如何重载，并复制唯一验证短句。可同时启用多个 Harness，回复统一排队朗读。"));
            foreach(var item in new[]{new[]{"codex","Codex"},new[]{"deepseek","DeepSeek Harness"},new[]{"claude","Claude Code"},new[]{"pi","pi"},new[]{"opencode","OpenCode"}}){string source=item[0],name=item[1];var check=new CheckBox{Text="启用",AutoSize=true,Height=30,Margin=new Padding(0,5,10,5)};checks[source]=check;Add(intro,Row(Hint(name),check,HarnessIndicator(source,name),AsyncBtn("自动接入并验证",async()=>await BeginVerification(source))));}
            Add(intro,Row(AsyncBtn("只保存启用开关",async()=>{var next=Json.Copy(Config);foreach(var key in Config.harness.Keys)next.harness[key]=checks[key].Checked;await Persist(next,new {harness=next.harness});await Poll();}),Btn("查看分步说明",()=>ShowPage("connectionGuide")),Btn("返回连接中心",()=>ShowPage("connections"))));
            Add(intro,Hint("只有“指定 Harness 返回本次随机短句，并完成实际语音播放”才变绿和播放礼炮。监听就绪、文件已安装、心跳在线、近期收到普通回复都不算验证通过。"));
            var advanced=Card(stack,"高级 · 项目级连接器导出");Add(advanced,Hint("通常不需要。仅当你明确希望连接器跟随某个项目时使用；不要和全局连接器重复加载。"));
            foreach(var item in new[]{new[]{"deepseek","DeepSeek"},new[]{"claude","Claude Code"},new[]{"pi","pi"},new[]{"opencode","OpenCode"}}){string source=item[0],name=item[1];Add(advanced,Row(AsyncBtn("导出到 "+name+" 项目",async()=>{using(var dialog=new FolderBrowserDialog{Description="选择 "+name+" 使用的项目目录",ShowNewFolderButton=false})if(dialog.ShowDialog(this)==DialogResult.OK){await Service.RunTool("export_connector.py","--source "+source+" --root "+ServiceClient.Quote(Store.Root)+" --project "+ServiceClient.Quote(dialog.SelectedPath));Status("项目连接器已导出；请重载 "+name+"。导出完成不表示验证成功。");}})));}
            BuildConnectionGuide();
        }
        void BuildAiri(){
            var stack=Stack(NewPage("airi"));var playback=Card(stack,"AIRI 输出选择");
            Add(playback,Hint("AIRI 联动完全可选。选择本机时，不启动 AIRI 也能正常播放；选择桌宠时，Harness 回复与 AIRI 自己的聊天语音都走桌宠原生播放与嘴型。"));
            outputChoice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=360};outputChoice.Items.AddRange(new object[]{"本机音频设备（local）","AIRI 桌宠播放与嘴型（airi）"});Add(playback,Row(Hint("音频最终从哪里播放"),outputChoice));Add(playback,Hint("本机音频设备（local）：由这台电脑当前选择的扬声器或耳机直接播放，不需要启动 AIRI。local 是程序内部保存的模式名称。"));var enabled=new CheckBox{Text="启用 AIRI 桌宠联动",AutoSize=true};checks["airiEnabled"]=enabled;Add(playback,Row(enabled));
            Add(playback,Row(AsyncBtn("保存播放设置",async()=>{var next=Json.Copy(Config);next.airi.enabled=checks["airiEnabled"].Checked;next.airi.directory=fields["airiDirectory"].Text.Trim();next.airi.output=outputChoice.SelectedIndex==1?"airi":"local";await Persist(next,new {airi=next.airi});Status(next.airi.enabled?"AIRI 联动设置已保存。":"AIRI 联动已关闭，本机音频设备仍可正常播放。");})));
            var connect=Card(stack,"自动接入并做真实播放验证");
            Add(connect,Hint("启动语音服务后点击一次。若未接入，选择你已经登录过、且目录中含 airi.exe 的原 AIRI。程序会准备联动副本并沿用原 ai.moeru.airi 用户资料；不会新建空白账号，也不会强制绑定。"));PathField(connect,"airiDirectory","已选择的原 AIRI 安装目录","",true);fields["airiDirectory"].Text="";airiIndicator=Hint("AIRI · 尚未通过播放验证");Add(connect,airiIndicator);
            Add(connect,Row(AsyncBtn("自动接入并验证 AIRI",async()=>await BeginVerification("airi")),Btn("打开已登录的 AIRI",OpenLoggedAiri),Btn("查看分步说明",()=>ShowPage("connectionGuide")),Btn("返回连接中心",()=>ShowPage("connections"))));
            Add(connect,Hint("验证测试音频必须经桌宠播放完成并返回回执后才变绿和播放礼炮。仅连接心跳、打开窗口或降级到本机播放都不会误报成功；启动较慢时，桥接连通后会自动继续验证。"));
            var manual=Card(stack,"高级 · 手动连接信息");Add(manual,Hint("仅在自动联动不适用时使用。AIRI 的 TTS 提供方填入下面的本机地址；账号仍由 AIRI 自己管理。"));Add(manual,Row(Btn("复制 AIRI 连接信息",()=>{Clipboard.SetText("Base URL: http://127.0.0.1:"+Config.port+"/v1/\r\nAPI Key: "+Config.token+"\r\nModel: agent-voice-tts\r\nVoice: current");Status("AIRI 手动连接信息已复制。");})));
        }
        void BuildConnectionHub(){var stack=Stack(NewPage("connections"));var start=Card(stack,"连接与联动");Add(start,Hint("先确定你要接入哪一类。Harness 负责把最终回复交给语音队列；AIRI 负责桌宠自身聊天发声，也可以接管 Harness 音频的播放和嘴型。两者互不强制绑定。"));Add(start,Row(EntryBtn("接入 Harness","配置 Codex、DeepSeek Harness、Claude Code、pi 或 OpenCode，并用随机短句做真实朗读验证。",()=>ShowPage("harness")),EntryBtn("联动 AIRI 桌宠","选择已登录的 AIRI、设置播放位置，并验证桌宠播放完成回执。",()=>ShowPage("airi")),EntryBtn("完整接入说明","查看每种客户端的重载方法、验证标准和故障排查。",()=>ShowPage("connectionGuide"))));var flow=Card(stack,"推荐顺序");Add(flow,Hint("1. 首页应用本地 TTS 并手动朗读成功。\r\n2. 启动语音服务。\r\n3. 进入 Harness 或 AIRI 页面，点击“自动接入并验证”。\r\n4. 按页面提示重载目标客户端。\r\n5. 完成随机短句或桌宠播放验证；看到绿色状态和礼炮才算成功。"));Add(flow,Hint("换电脑或移动程序后重新定位并验证。接入程序只合并自己的连接器；原有账号、模型和无关插件保留。"));}
        void BuildCleanup(){var card=SettingsCard("cleanup","音频清理");Add(card,Hint("音频目录："+Store.Resolve("data/output")));Add(card,Row(Btn("打开音频目录",()=>{Directory.CreateDirectory(Store.Resolve("data/output"));ServiceClient.Open(Store.Resolve("data/output"));})));NumberField(card,"maxAgeMinutes","删除超过（分钟）",1,43200,1,0);NumberField(card,"keepLatest","保留最新文件数",0,10000,1,0);NumberField(card,"maxTotalMb","总占用上限（MB）",1,100000,10,0);Add(card,Row(AsyncBtn("保存并清理",async()=>{var next=Json.Copy(Config);next.cleanup.maxAgeMinutes=(int)numbers["maxAgeMinutes"].Value;next.cleanup.keepLatest=(int)numbers["keepLatest"].Value;next.cleanup.maxTotalMb=(int)numbers["maxTotalMb"].Value;await Persist(next,new {cleanup=next.cleanup});var result=await Service.Request("/api/cleanup",new {});Status("已清理 "+result["removed"]+" 个音频。");}),AsyncBtn("清空已完成音频",async()=>{var result=await Service.Request("/api/cleanup",new {all=true});Status("已清理 "+result["removed"]+" 个音频，生成或播放中的文件受到保护。");})));
        }
        void BindSettings(){fields["accent"].Text=Config.appearance.accent;fields["backgroundColor"].Text=Config.appearance.backgroundColor;fields["textColor"].Text=Config.appearance.textColor;fields["background"].Text=Config.appearance.background;fields["pythonRvc"].Text=Config.engines.pythonRvc;fields["rvcHome"].Text=Config.engines.rvcHome;fields["pythonTts"].Text=Config.engines.pythonTts;fields["cosyRepo"].Text=Config.engines.cosyRepo;fields["cosyModel"].Text=Config.engines.cosyModel;fields["airiDirectory"].Text=Config.airi.directory;outputChoice.SelectedIndex=Config.airi.output=="airi"?1:0;checks["airiEnabled"].Checked=Config.airi.enabled;foreach(var key in Config.harness.Keys)checks[key].Checked=Config.harness[key];numbers["maxAgeMinutes"].Value=Config.cleanup.maxAgeMinutes;numbers["keepLatest"].Value=Config.cleanup.keepLatest;numbers["maxTotalMb"].Value=Config.cleanup.maxTotalMb;}
